package io.github.miklires.mclans.clan;
import java.util.List;
public final class ClanProgression {private final List<Level> levels;public ClanProgression(List<Level> levels){this.levels=List.copyOf(levels);if(levels.isEmpty()||levels.getFirst().level()!=1)throw new IllegalArgumentException("Clan levels must start at 1");long points=-1;int number=0;for(Level level:levels){if(level.level()!=number+1||level.requiredPoints()<=points)throw new IllegalArgumentException("Clan levels must be sequential with increasing points");number=level.level();points=level.requiredPoints();}}public Level forPoints(long points){Level result=levels.getFirst();for(Level level:levels)if(points>=level.requiredPoints())result=level;return result;}public record Level(int level,long requiredPoints,int memberLimit){public Level{if(level<1||requiredPoints<0||memberLimit<1||memberLimit>1000)throw new IllegalArgumentException("Invalid clan level");}}}
